/**
 * Emits the WebSocket protocol as JSON Schema, for consumers that are not
 * TypeScript.
 *
 * zod stays the single source of truth: `apps/daemon-rs` generates its Rust
 * types from this file at build time, so the two languages cannot drift.
 * Regenerated by `npm run generate:json-schema` and checked in CI.
 */
import { mkdir, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { z } from "zod";

const packageRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const outputDir = resolve(packageRoot, "generated");

const { WSInboundMessageSchema, WSOutboundMessageSchema } = await import(
  resolve(packageRoot, "dist/messages.js")
);

function toJsonSchema(schema, io) {
  return z.toJSONSchema(schema, {
    io,
    // Dates, functions and the like have no JSON Schema equivalent; `any` keeps
    // generation total rather than failing on a handful of fields.
    unrepresentable: "any",
    cycles: "ref",
    // schemars 0.8, which typify consumes, models draft-07.
    target: "draft-7",
  });
}

// One self-contained document per direction. Nesting both under a shared
// `$defs` would break zod's `$ref` paths, which are relative to each schema's
// own root.
const documents = [
  ["ws-inbound.schema.json", "WSInboundMessage", WSInboundMessageSchema, "input"],
  ["ws-outbound.schema.json", "WSOutboundMessage", WSOutboundMessageSchema, "output"],
];

await mkdir(outputDir, { recursive: true });
for (const [filename, title, schema, io] of documents) {
  const document = { title, ...toJsonSchema(schema, io) };
  const output = resolve(outputDir, filename);
  await writeFile(output, `${JSON.stringify(document, null, 2)}\n`);
  process.stdout.write(`Wrote ${output}\n`);
}
